  ('hs0', 'high-signal', '1', 'How to set up your first home meeting: the checklist we use. Read it before your first one.', null, '{"type":"link","target":{"kind":"material","id":"lib-2"}}'::jsonb, seed_tmp.ts(-2603425), null, null),
  ('hs1', 'high-signal', '1', 'Bring two guests to every open meeting, even if they say maybe. Half of the maybes end up coming.', null, null, seed_tmp.ts(-1735825), null, null),
  ('d13a', 'dm-1-3', '3', '', null, null, seed_tmp.ts(-346225), null, null),
  ('an1', 'announcements', '1', 'Welcome to LevelUp chats! Announcements, Main chat, Daily wins and High signal are pinned at the top of Groups, and direct messages have their own tab. Pin any chat you use a lot.', null, null, seed_tmp.ts(-303025), null, null),
  ('d17a', 'dm-1-7', '1', 'Did you grab your ticket yet?', null, null, seed_tmp.ts(-292225), null, null),
  ('d12a', 'dm-1-2', '1', 'Can we go over your Fall Weekend list this week?', null, null, seed_tmp.ts(-101425), null, null),
  ('d12b', 'dm-1-2', '2', 'Sounds good, talk tomorrow', null, null, seed_tmp.ts(-99625), null, null),
  ('cp1', 'carpool', '3', 'Starting a carpool thread for the Fall Weekend. Who needs a ride?', null, null, seed_tmp.ts(-97825), null, null),
  ('cp2', 'carpool', '7', 'Me please! I''m flying into Dallas though, can someone grab me at the airport?', null, null, seed_tmp.ts(-96625), null, null),
  ('cp3', 'carpool', '3', 'Here''s the route from Plano', null, null, seed_tmp.ts(-94225), null, null),
  ('cp4', 'carpool', '3', 'I can take 3 from Plano', null, null, seed_tmp.ts(-93925), null, null),
  ('mc1', 'main', '1', 'Great meeting last night, everyone. This month the focus is Fall Weekend tickets.', null, null, seed_tmp.ts(-90625), null, null),
  ('mc2', 'main', '3', 'Thanks Maria! My team is on it.', null, null, seed_tmp.ts(-88825), null, null),
  ('d24a', 'dm-2-4', '4', 'Thanks for the help with the plan yesterday!', null, null, seed_tmp.ts(-87025), null, null),
  ('hs2', 'high-signal', '1', 'Fall Leadership Weekend is coming up. Tap below so we can plan rooms and rides.', null, '{"type":"event","eventId":"e1"}'::jsonb, seed_tmp.ts(-18000), null, null),
  ('dw1', 'daily-wins', '1', '', null, '{"type":"win","winKind":"ticket","refId":"a1","title":"Bought my ticket","detail":"Fall Leadership Weekend"}'::jsonb, seed_tmp.ts(-14400), null, null),
  ('hs3', 'high-signal', '4', '@Maria Reyes does this still apply for the Fall Weekend? I have two prospects who might come.', 'hs1', null, seed_tmp.ts(-14400), null, null),
  ('hs4', 'high-signal', '1', 'Yes! Bring them both. Book them into the Saturday session.', 'hs3', null, seed_tmp.ts(-12900), null, null),
  ('hs5', 'high-signal', '2', 'Quick thought on inviting, and the talk that helped me most:', null, '{"type":"link","target":{"kind":"material","id":"lib-1"}}'::jsonb, seed_tmp.ts(-10800), null, null),
